  out.notes.push(audit.map(a=>a.label+': '+a.valid+' valid, '+a.missing+' missing, '+a.invalid+' unrecognised').join('; ')+'.');
  out.demographicNarrative='Among '+rows.length+' recorded participants, median age (Q1–Q3) was '+out.rows[0][1]+' years; '+out.rows[4][1]+' of '+out.rows[4][2]+' participants with recorded sex were male. '+audit.map(a=>{if(!a.valid)return a.label+' had no recognised responses and cannot be summarised as a category distribution.';const c=[...a.categories].sort((a,b)=>b.n-a.n)[0];return 'For '+a.label.toLowerCase()+', the most frequent recorded category was '+c.label+' ('+c.n+'/'+a.valid+', '+(100*c.n/a.valid).toFixed(1)+'%).';}).join(' ')+' These distributions describe the social background of this operated cohort alongside its age and sex profile; they do not establish demographic differences in appendicitis diagnosis, severity, diagnostic confidence or hospital expenditure.';
